'use strict';
(()=>{
const app=document.querySelector('#app'),q=new URLSearchParams(location.search),edition=q.get('edition')==='law'?'law':'one',plan=q.get('plan')==='team'?'team':'creator',name=edition==='law'?'Vibe Law':'Vibe One',planName=plan==='team'?'Team':'Creator',unit=edition==='law'?(plan==='team'?59:29):(plan==='team'?49:19),key='vibe-demo-order-v1';
document.querySelector('#brand-edition').textContent=edition==='law'?' Law':' One';
const url=(page,p=plan)=>'/'+page+'/?edition='+edition+'&plan='+p;
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
let seats=plan==='team'?Math.max(3,Math.min(50,Number.isInteger(Number(q.get('seats')))?Number(q.get('seats')):3)):1;
let receipt=null;try{receipt=JSON.parse(sessionStorage.getItem(key));}catch{}
function validReceipt(r){return r&&r.demo===true&&/^(one|law)$/.test(r.edition)&&/^(creator|team)$/.test(r.plan)&&/^DEMO-[A-Z0-9-]+$/.test(r.id)&&Number.isFinite(Date.parse(r.created))&&Number.isInteger(r.seats)&&r.seats>0&&r.seats<=50&&r.total===(r.edition==='law'?(r.plan==='team'?59:29):(r.plan==='team'?49:19))*r.seats;}
if(!validReceipt(receipt))receipt=null;
function renderReceipt(r){
app.innerHTML='<section class="receipt"><div class="receipt-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></div><p class="eyebrow">DEMO ORDER CONFIRMED</p><h1>Your test order is complete.</h1><p class="intro">You have reached the end of the purchase flow. No money was charged, and no paid subscription was activated.</p><div class="card"><h2>Demo receipt</h2><div id="receipt-lines"></div></div><div class="actions"><a class="button primary" href="/">Return to Workbench</a><a class="button" href="'+url('plans')+'">Try another plan</a><button id="new-order">Start a new demo order</button></div><p class="muted">This receipt is stored in this browser tab for the demo only.</p></section>';
const lines=[['Order',r.id],['Offering',r.edition==='law'?'Vibe Law':'Vibe One'],['Plan',r.plan==='team'?'Team':'Creator'],['Seats',String(r.seats)],['Billing','Monthly · simulation'],['Demo total',usd(r.total)],['Amount charged',usd(0)],['Created',new Date(r.created).toLocaleString()]];
for(const [label,value] of lines){const row=document.createElement('div');row.className='line';const l=document.createElement('span'),v=document.createElement('strong');l.textContent=label;v.textContent=value;row.append(l,v);document.querySelector('#receipt-lines').append(row);}
document.querySelector('#new-order').onclick=()=>{try{sessionStorage.removeItem(key);}catch{}receipt=null;history.replaceState(null,'',url('checkout'));renderCheckout();};
}
if(document.body.dataset.page==='plans'){
app.innerHTML='<p class="eyebrow">01 / CHOOSE YOUR PLAN</p><h1>A space for your next idea.</h1><p class="intro">Choose the offering and plan you want to try. Continue as a guest through a simulated purchase, with no sign-in required.</p><div class="switch" aria-label="Choose offering"><a href="/plans/?edition=one" aria-current="'+(edition==='one')+'">Vibe One</a><a href="/plans/?edition=law" aria-current="'+(edition==='law')+'">Vibe Law</a></div><div class="notice"><strong>Demo pricing.</strong> These proposed plans are for testing the purchase flow. No payment details are requested.</div><div class="grid">'+['creator','team'].map(p=>{const price=edition==='law'?(p==='team'?59:29):(p==='team'?49:19);return '<article class="card"><p class="eyebrow">'+name.toUpperCase()+'</p><h2>'+(p==='team'?'Team':'Creator')+'</h2><p>'+(p==='team'?'For a team building together.':'For your own ideas and projects.')+'</p><div class="price">'+usd(price)+' <small>/ '+(p==='team'?'seat / ':'')+'month</small></div><p class="muted">'+(p==='team'?'Minimum 3 seats · choose 3–50 at checkout.':'One seat · monthly billing simulation.')+'</p><ul><li>Proposed '+(p==='team'?'shared':'personal')+' workspace</li><li>Project briefs and coding practice</li><li>Codex workflow · model usage separate</li></ul><a class="button primary" href="'+url('checkout',p)+'">Choose '+(p==='team'?'Team':'Creator')+'</a></article>';}).join('')+'</div>';
return;
}
function renderCheckout(){
app.innerHTML='<p class="eyebrow">02 / DEMO CHECKOUT</p><h1>Review your order.</h1><p class="intro">You are checking out as a guest. Use Admin Pay to run the demo order.</p><div class="checkout-grid"><section><div class="card"><h2>'+name+' · '+planName+'</h2><p>Monthly plan simulation for '+(plan==='team'?'your team.':'one person.')+'</p>'+(plan==='team'?'<label for="seats">Seats (3–50)</label><input id="seats" type="number" min="3" max="50" step="1" value="'+seats+'"><p id="seat-error" class="error" role="status"></p>':'<p>1 seat</p>')+'<a href="'+url('plans')+'">Change offering or plan</a></div><div class="notice">No card, email, or ChatGPT sign-in is needed. Admin Pay creates a simulated receipt only.</div></section><section class="card" aria-label="Order summary"><h2>Order summary</h2><div class="line"><span>'+planName+' / seat / month</span><strong>'+usd(unit)+'</strong></div><div class="line"><span>Seats</span><strong id="count">'+seats+'</strong></div><div class="line total"><span>Demo monthly total</span><span id="total">'+usd(unit*seats)+'</span></div><div class="line"><span>Amount charged today</span><strong>$0.00</strong></div><p class="muted">USD · demo only. No charge, recurring billing, or subscription activation.</p><button class="primary" id="admin-pay">Admin Pay · demo</button></section></div><dialog id="pay-dialog" aria-labelledby="pay-heading"><form id="pay-form"><h2 id="pay-heading">Run a demo order</h2><p>Enter the demo passkey <strong>12345</strong> to simulate payment.</p><label for="passkey">Demo passkey</label><input id="passkey" name="passkey" type="password" inputmode="numeric" autocomplete="off" required><p id="pay-error" class="error" role="alert"></p><div class="actions"><button class="primary" type="submit">Complete demo order</button><button type="button" id="cancel-pay">Cancel</button></div><p class="muted">No real payment will be made.</p></form></dialog>';
const input=document.querySelector('#seats'),pay=document.querySelector('#admin-pay'),dialog=document.querySelector('#pay-dialog');
function checkSeats(){if(!input)return true;const n=Number(input.value),ok=Number.isInteger(n)&&n>=3&&n<=50;document.querySelector('#seat-error').textContent=ok?'':'Choose a whole number from 3 to 50.';pay.disabled=!ok;if(ok){seats=n;document.querySelector('#count').textContent=n;document.querySelector('#total').textContent=usd(unit*n);const next=new URL(location.href);next.searchParams.set('seats',String(n));history.replaceState(null,'',next);}return ok;}
if(input)input.oninput=checkSeats;
pay.onclick=()=>{if(!checkSeats())return;document.querySelector('#pay-error').textContent='';dialog.showModal();document.querySelector('#passkey').focus();};
document.querySelector('#cancel-pay').onclick=()=>dialog.close();
let completing=false;document.querySelector('#pay-form').onsubmit=e=>{e.preventDefault();if(completing)return;if(document.querySelector('#passkey').value!=='12345'){document.querySelector('#pay-error').textContent='Incorrect demo passkey. Use 12345.';return;}if(!checkSeats())return;completing=true;e.submitter.disabled=true;
receipt={demo:true,id:'DEMO-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)).toUpperCase(),edition,plan,seats,total:unit*seats,created:new Date().toISOString()};try{sessionStorage.setItem(key,JSON.stringify(receipt));}catch{}dialog.close();const next=new URL(location.href);next.searchParams.set('receipt',receipt.id);history.replaceState(null,'',next);renderReceipt(receipt);};
}
if(receipt&&q.get('receipt')===receipt.id)renderReceipt(receipt);else renderCheckout();
})();
